local procedure IsSystemTableExcluded(TableId: Integer): Boolean
var
    ExcludedTables: array[19] of Integer;
    i: Integer;
begin
    if TableId = 0 then
        exit(false); // synthetic entries (Session Runtime Error) must never be excluded
    ExcludedTables[1] := Database::"Change Log Entry";
    // ... (remaining 18 entries unchanged)
    for i := 1 to ArrayLen(ExcludedTables) do
        if ExcludedTables[i] = TableId then
            exit(true);
    exit(false);
end;

